components.css:
.ds-faceplate { display: flex; align-items: center; gap: 24px; padding: 13px 28px; background: #17191d; border-top: 1px solid rgba(255,255,255,0.08); font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; user-select: none; }
.ds-faceplate-screw { flex: none; width: 9px; height: 9px; border-radius: 50%; background: #101215; border: 1px solid #0a0b0d; box-shadow: inset 0 1px 1px rgba(255,255,255,0.07); }
.ds-name { display: flex; flex-direction: column; gap: 3px; line-height: 1; }
.ds-name-word { font-size: 15px; font-weight: 700; letter-spacing: 0.34em; color: #e8e3d5; }
.ds-name-sub { font-size: 9px; font-weight: 600; letter-spacing: 0.24em; color: #9aa0ab; }
.ds-faceplate-seam { width: 1px; align-self: stretch; background: #0d0f12; }

.ds-readout { display: flex; align-items: center; gap: 11px; padding-left: 24px; border-left: 1px solid #0d0f12; line-height: 1; font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; }
.ds-readout-label { font-size: 10px; font-weight: 700; letter-spacing: 0.16em; color: #c3c8d1; }
.ds-meter { display: inline-flex; gap: 3px; }
.ds-seg { width: 9px; height: 16px; background: #232730; border: 1px solid #0e1013; }
.ds-seg.lit { background: #f2d43a; border-color: #a98f1d; box-shadow: 0 0 6px rgba(242,212,58,0.45); }
.ds-count { min-width: 2.5ch; text-align: right; font-family: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; color: #f2d43a; }
.ds-count.is-zero { color: #9aa0ab; }

.ds-btn { display: inline-flex; align-items: center; gap: 9px; appearance: none; background: #242930; color: #d9dde4; border: 1px solid #0e1013; border-radius: 2px; padding: 9px 12px 9px 14px; font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 11px; font-weight: 700; letter-spacing: 0.14em; cursor: pointer; box-shadow: inset 0 1px 0 rgba(255,255,255,0.07); }
.ds-btn:hover { background: #2b313a; }
.ds-btn:active { background: #1f242b; box-shadow: inset 0 1px 3px rgba(0,0,0,0.55); }
.ds-btn:focus-visible { outline: 2px solid #f2d43a; outline-offset: 3px; }
.ds-key { font-family: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 10px; font-weight: 600; color: #b6bcc6; background: #2c323b; border: 1px solid #3d444d; border-radius: 2px; padding: 2px 6px; min-width: 10px; text-align: center; }

.ds-zone-face { position: relative; width: 128px; height: 128px; background: #2a2d31; border: 6px solid #15171a; outline: 2px solid rgba(255,255,255,0.06); }
.ds-zone-id { position: absolute; top: 14px; left: 15px; font-family: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 12px; font-weight: 700; color: #8f96a0; }
.ds-zone-pad { position: absolute; left: 32px; top: 59px; width: 64px; height: 28px; border-radius: 5px; background: #2fbd72; border: 1px solid rgba(0,0,0,0.45); }
